 this.current(t,abort.signal);const message:ChatMessage={id:randomUUID(),conversationId:t.conversationId,turnId:id,role:'assistant',content:final,createdAt:now(),citations:[...citations(t.results.prepare_application||t.results.prepare_enquiry||t.results.retrieve_guidance),...citations(t.results.search_business_knowledge)],actions};this.store.put('chat_message',message.id,t.caseId,message);t.status=actions.some(a=>a.type==='confirm_facts')?'needs_input':'completed';t.updatedAt=now();this.saveTurn(t);
